/// <summary>
/// Extension of the SalesFormletterParmDataInvoice class to support custom logic during sales order invoice processing, specifically for calculating invoice amounts based on picked quantities.
/// </summary>
[Extensionof(classStr(SalesFormletterParmDataInvoice))]
internal final class METSalesFormletterParmDataInvoice_Extension
{
}

Method.Source:
/// <summary>
/// Inserts a sales parameter line into the invoice.
/// </summary>
/// <param name = "_parmLine">Common</param>
protected void insertParmLine(Common _parmLine)
{
    SalesParmLine salesParmLine = _parmLine as SalesParmLine;

    SalesLine salesLine = SalesLine::findRecId(salesParmLine.SalesLineRecId);  
    SalesTable salesTableLoc = salesLine.salestable();
    PdsCWUnitId pdsCWUnitId = salesLine.pdsCWUnitId();

    if (CustParameters::find().METCalcInvOnPickAmounts && salesTableLoc.SalesType != SalesType::ReturnItem)
    {
        if (salesLine.metDisplayPickedCases())
        {
            salesParmLine.DeliverNow = salesLine.metDisplayPickedCases();
            salesParmLine.setQty(DocumentStatus::Invoice, true, true);
            salesParmLine.setLineAmount(salesLine);
            salesParmLine.calcPackingUnitQty();
        }
        else if (salesLine.metDisplayPickedBrokenCases())
        {
            salesParmLine.DeliverNow = salesLine.metDisplayPickedBrokenCases();
            salesParmLine.setQty(DocumentStatus::Invoice, true, true);
            salesParmLine.setLineAmount(salesLine);
            salesParmLine.calcPackingUnitQty();
        }
    }
    if (salesTableLoc.salestype == SalesType::ReturnItem && pdsCWUnitId && SalesParmLine::isCWClaimCreditApplicable(salesLine))
    {
        METCWReturnWeight cwRetWeight = salesLine.metSalesLine().CWReturnWeight;

        if (cwRetWeight)
        {
            salesParmLine.DeliverNow = salesLine.metSalesLine().CWReturnWeight;
            salesParmLine.setQty(DocumentStatus::Invoice, true, true);
        }
        else
        {
            throw error ("@MET:CWQtyValid");
        }
    }

    next insertParmLine(_parmLine);
}
